def int_to_mini_roman(number):
    roman_dict = {
        "I": 1,
        "V": 5,
        "X": 10,
        "L": 50,
        "C": 100,
        "D": 500,
        "M": 1000
    }

    result = ""
    while number > 0:
        if number >= roman_dict["M"]:
            result += "M"
            number -= roman_dict["M"]
        elif number >= roman_dict["D"]:
            result += "D"
            number -= roman_dict["D"]
        elif number >= roman_dict["C"]:
            result += "C"
            number -= roman_dict["C"]
        elif number >= roman_dict["L"]:
            result += "L"
            number -= roman_dict["L"]
        elif number >= roman_dict["X"]:
            result += "X"
            number -= roman_dict["X"]
        else:
            result += "I"
            number -= roman_dict["I"]

    return result.lower()
```
